+		uuid_t **uuids, **old_uuids;
+
+		uuids = kcalloc(ti->uuids_len * 2, sizeof(*uuids), GFP_KERNEL);
+		if (!uuids)
+			return -ENOMEM;
+
+		/* Copy/move old allocated UUIDs */
+		for (int i = 0; i < ti->info.num_uuids; i++)
