 		     bool operational)
@@ -2032,8 +2165,9 @@ static const struct dsa_switch_ops qca8k_switch_ops = {
 	.port_vlan_del		= qca8k_port_vlan_del,
 	.phylink_get_caps	= qca8k_phylink_get_caps,
